'use strict';
// Writes a generated workflow into a target project directory.
// - Plain generated files are written as-is (and tracked in .agent/manifest.json).
// - CLAUDE.md gets a marker-delimited managed block; the rest of the file is untouched.
// - .claude/settings.json gets one SessionStart hook entry merged in; other settings are untouched.
// - Files generated by a previous run that are no longer part of the design are removed,
//   but only if they still carry the generator marker (hand-written files are never deleted).

const fs = require('fs');
const path = require('path');
const gen = require('../public/generator.js');
const backups = require('./backup');

const BLOCK_START = '<!-- agent-visualizer:start -->';
const BLOCK_END = '<!-- agent-visualizer:end -->';
const MANIFEST = '.agent/manifest.json';

function safeJoin(root, rel) {
  const abs = path.resolve(root, rel);
  if (abs !== root && !abs.startsWith(root + path.sep)) throw new Error('Refusing to write outside the project: ' + rel);
  return abs;
}

function readJson(file, fallback) {
  try {
    return JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch (_) {
    return fallback;
  }
}

function mergeClaudeMd(existing, block) {
  const managed = BLOCK_START + '\n' + block + '\n' + BLOCK_END;
  if (!existing) return managed + '\n';
  const s = existing.indexOf(BLOCK_START);
  const e = existing.indexOf(BLOCK_END);
  if (s !== -1 && e > s) return existing.slice(0, s) + managed + existing.slice(e + BLOCK_END.length);
  return existing.replace(/\s*$/, '') + '\n\n' + managed + '\n';
}

function mergeSettings(settings, hook) {
  const out = settings && typeof settings === 'object' && !Array.isArray(settings) ? settings : {};
  out.hooks = out.hooks && typeof out.hooks === 'object' ? out.hooks : {};
  const list = Array.isArray(out.hooks[hook.event]) ? out.hooks[hook.event] : [];
  // Drop any previous entry of ours, keep everything else.
  const kept = list
    .map((group) => {
      if (!group || !Array.isArray(group.hooks)) return group;
      const hooks = group.hooks.filter((h) => !(h && typeof h.command === 'string' && h.command.includes('.agent/session-context.md')));
      return hooks.length ? Object.assign({}, group, { hooks }) : null;
    })
    .filter(Boolean);
  kept.push({ matcher: hook.matcher, hooks: [{ type: 'command', command: hook.command }] });
  out.hooks[hook.event] = kept;
  return out;
}

function removeEmptyDirs(root, rel) {
  let dir = path.dirname(safeJoin(root, rel));
  while (dir.startsWith(root + path.sep)) {
    try {
      if (fs.readdirSync(dir).length) return;
      fs.rmdirSync(dir);
    } catch (_) {
      return;
    }
    dir = path.dirname(dir);
  }
}

function writeProject(projectDir, design) {
  const root = path.resolve(projectDir);
  if (!fs.existsSync(root) || !fs.statSync(root).isDirectory()) throw new Error('Project directory does not exist: ' + root);
  const result = gen.generate(design);
  if (result.errors.length) {
    const err = new Error('Design has errors');
    err.details = result.errors;
    throw err;
  }

  const written = [];
  const removed = [];
  const backedUp = [];
  const previous = readJson(path.join(root, MANIFEST), { files: [] }).files || [];

  for (const [rel, content] of Object.entries(result.files)) {
    const abs = safeJoin(root, rel);
    fs.mkdirSync(path.dirname(abs), { recursive: true });
    // Never silently replace a hand-written file (e.g. an existing agent with the same name).
    if (fs.existsSync(abs) && !previous.includes(rel) && rel !== '.agent/.gitignore') {
      const old = fs.readFileSync(abs, 'utf8');
      if (!old.includes(gen.MARKER) && old !== content) {
        // Saved in the version history (.agent/backups/...), so it can be rolled back from the GUI.
        backups.backup(root, abs, 'replaced by a generated agent');
        backedUp.push(rel);
      }
    }
    fs.writeFileSync(abs, content);
    if (rel.endsWith('.sh')) fs.chmodSync(abs, 0o755);
    written.push(rel);
  }

  // CLAUDE.md managed block
  const claudeMdPath = safeJoin(root, 'CLAUDE.md');
  const existingMd = fs.existsSync(claudeMdPath) ? fs.readFileSync(claudeMdPath, 'utf8') : '';
  fs.writeFileSync(claudeMdPath, mergeClaudeMd(existingMd, result.claudeMd));
  written.push('CLAUDE.md (managed block)');

  // .claude/settings.json SessionStart hook
  const settingsPath = safeJoin(root, '.claude/settings.json');
  fs.mkdirSync(path.dirname(settingsPath), { recursive: true });
  let settings = {};
  if (fs.existsSync(settingsPath)) {
    const raw = fs.readFileSync(settingsPath, 'utf8');
    try {
      settings = JSON.parse(raw);
    } catch (e) {
      throw new Error('.claude/settings.json is not valid JSON; fix it first so it can be merged safely (' + e.message + ')');
    }
  }
  fs.writeFileSync(settingsPath, JSON.stringify(mergeSettings(settings, result.hook), null, 2) + '\n');
  written.push('.claude/settings.json (SessionStart hook)');

  // Stale files from the previous generation
  const now = new Set(Object.keys(result.files));
  for (const rel of previous) {
    if (now.has(rel)) continue;
    let abs;
    try {
      abs = safeJoin(root, rel);
    } catch (_) {
      continue;
    }
    if (!fs.existsSync(abs)) continue;
    const content = fs.readFileSync(abs, 'utf8');
    if (!content.includes(gen.MARKER) && !rel.endsWith('.gitignore')) continue;
    fs.unlinkSync(abs);
    removeEmptyDirs(root, rel);
    removed.push(rel);
  }

  const manifestFiles = Object.keys(result.files).sort();
  fs.writeFileSync(
    path.join(root, MANIFEST),
    JSON.stringify({ generator: 'agent-visualizer', generatedAt: new Date().toISOString(), files: manifestFiles }, null, 2) + '\n'
  );
  written.push(MANIFEST);

  return { projectDir: root, written, removed, backedUp, warnings: result.warnings };
}

module.exports = { writeProject, mergeClaudeMd, mergeSettings, BLOCK_START, BLOCK_END };
